 if kind=='Article':graph.append({'@type':'Article','headline':title.split(' | ')[0],'description':desc,'image':image,'mainEntityOfPage':{'@id':canonical+'#webpage'},'author':{'@type':'Organization','name':BRAND,'url':DOMAIN+'/nosotros.html'},'publisher':{'@type':'Organization','name':BRAND,'url':DOMAIN+'/'},'datePublished':DATE,'dateModified':DATE,'inLanguage':'es'})
