 content+=f'<script src="{relative(path)}assets/js/app.js" defer></script>'
 if path=='index.html':content+='<script src="assets/js/wordmark-data.js" defer></script><script src="assets/js/wordmark.js" defer></script>'
 content+='</body></html>'
 target=SITE/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
